//@ts-check

import {
  isStringType,
} from '@jarenjs/core';

import {
  getIntishType,
} from '@jarenjs/core/number';

import {
  countCodePoints,
  createRegExpTester,
  getStringLength,
} from '@jarenjs/core/string';

import {
  trueThat,
} from '@jarenjs/core/function';

import { isDollarDataRef } from './schema-keywords.js';

/**
 * The unit `minLength` and `maxLength` count in, from a validator's
 * options: `lengthUnit` when set, else `useGrapheme` read for truth as it
 * always was (true, the default, is `'grapheme'`; false is `'utf16'`).
 * @param {{ lengthUnit?: 'grapheme'|'codepoint'|'utf16', useGrapheme?: boolean }} options
 * @returns {'grapheme'|'codepoint'|'utf16'}
 */
export function lengthUnitOf(options) {
  return options.lengthUnit ?? (options.useGrapheme ? 'grapheme' : 'utf16');
}

/**
 * Refuse a `lengthUnit` that names no unit. Without this a misspelling is
 * silent: every bound would count graphemes, the unit the author opted out of.
 * @param {unknown} unit - The configured value; `undefined` (or `null`) leaves `useGrapheme` to decide
 * @throws {TypeError} When `unit` is not `'grapheme'`, `'codepoint'` or `'utf16'`
 */
export function assertLengthUnit(unit) {
  if (unit != null && unit !== 'grapheme' && unit !== 'codepoint' && unit !== 'utf16')
    throw new TypeError(`lengthUnit must be 'grapheme', 'codepoint' or 'utf16', got ${JSON.stringify(unit)}`);
}

/**
 * A string's length in a unit: grapheme clusters, code points (a lone
 * surrogate counts one, as a database counts the U+FFFD it is stored as) or
 * UTF-16 code units.
 * @param {'grapheme'|'codepoint'|'utf16'} unit
 * @returns {(data: string) => number}
 */
export function stringLengthIn(unit) {
  if (unit === 'codepoint') return countCodePoints;
  return unit === 'utf16' ? utf16Length : graphemeLength;
}
/** @param {string} data */
function utf16Length(data) { return data.length; }
/** @param {string} data */
function graphemeLength(data) { return getStringLength(data, true); }

/**
 * Compile a JSON Schema regular expression (`pattern`, a
 * `patternProperties` key) into a repeatable predicate. A string is an
 * ECMA-262 pattern source, as JSON Schema 2020-12 Validation §6.3.3 reads
 * it, compiled in Unicode mode: `'/a/'` matches only text containing
 * `/a/`, never the `/source/flags` literal `createRegExp` would read. A
 * RegExp that JavaScript code placed in a schema keeps its own flags.
 *
 * A string that is no valid Unicode-mode source but compiles as a
 * `/source/flags` literal - a `v`-mode literal such as
 * `'/[\\p{L}--[a-z]]/v'` - is still read as that literal, as it always
 * was: refusing it would refuse a schema that compiles today.
 * @param {unknown} pattern - The keyword's value
 * @returns {((value: string) => boolean) | undefined} The tester, or
 *   `undefined` when no pattern is given
 * @throws {SyntaxError} When the string compiles neither way
 * @throws {Error} When the value is neither a string nor a RegExp
 */
export function createSchemaPatternTester(pattern) {
  if (typeof pattern !== 'string')
    return createRegExpTester(/** @type {RegExp | null | undefined} */ (pattern));
  let regexp;
  try {
    regexp = new RegExp(pattern, 'u');
  }
  catch (error) {
    let literal;
    try {
      literal = createRegExpTester(pattern);
    }
    catch (_literalError) {
      throw error;
    }
    return literal;
  }
  return (value) => regexp.test(value);
}

function compileMinLength(schemaObj, jsonSchema) {
  const min = getIntishType(jsonSchema.minLength) || 0;
  if (min < 1) return undefined;

  const addError = schemaObj.createErrorHandler(min, 'minLength');

  return function validateIsMinLength(len = 0, dataPath) {
    return len >= min
      || addError(len, dataPath);
  };
}

function compileMaxLength(schemaObj, jsonSchema) {
  const max = getIntishType(jsonSchema.maxLength) ?? -1;
  if (max < 0) return undefined;

  const addError = schemaObj.createErrorHandler(max, 'maxLength');

  return function validateIsMaxLength(len = 0, dataPath) {
    return len <= max
      || addError(len, dataPath);
  };
}

function compilePattern(schemaObj, jsonSchema) {
  // A $data reference is compiled with the $data keywords.
  if (isDollarDataRef(jsonSchema.pattern)) return undefined;

  const pattern = jsonSchema.pattern;
  const matches = createSchemaPatternTester(pattern);
  if (matches === undefined) return undefined;

  const addError = schemaObj.createErrorHandler(pattern, 'pattern');

  return function validateIsMatch(str = '', dataPath) {
    return matches(str)
      || addError(str, dataPath);
  };
}

function compileStringIntern(schemaObj, jsonSchema) {
  const minLength = compileMinLength(schemaObj, jsonSchema);
  const maxLength = compileMaxLength(schemaObj, jsonSchema);
  const pattern = compilePattern(schemaObj, jsonSchema);

  if ((minLength || maxLength || pattern) == null) return undefined;

  const isMinLength = minLength || trueThat;
  const isMaxLength = maxLength || trueThat;
  const isMatch = pattern || trueThat;
  const unit = lengthUnitOf(schemaObj.options);
  const useGrapheme = unit === 'grapheme';

  if (unit === 'codepoint') {
    if (schemaObj.options.skipErrors) {
      return function validateStringInternCodePoints(data, dataPath) {
        const len = countCodePoints(data);
        return isMinLength(len, dataPath)
          && isMaxLength(len, dataPath)
          && isMatch(data, dataPath);
      };
    }
    return function validateStringInternAllCodePoints(data, dataPath) {
      const len = countCodePoints(data);
      let valid = isMinLength(len, dataPath);
      valid = isMaxLength(len, dataPath) && valid;
      return isMatch(data, dataPath) && valid;
    };
  }

  if (schemaObj.options.skipErrors) {
    return function validateStringIntern(data, dataPath) {
      const len = getStringLength(data, useGrapheme);
      return isMinLength(len, dataPath)
        && isMaxLength(len, dataPath)
        && isMatch(data, dataPath);
    };
  }

  // Length and pattern are independent assertions over the same string:
  // `len` is computed before any of them and `isMatch` reads the raw data,
  // so a failed `minLength` says nothing about whether `pattern` holds.
  // Short-circuiting them is a boolean-mode optimization; when errors are
  // recorded it would hide half the reasons the value is wrong.
  return function validateStringInternAll(data, dataPath) {
    const len = getStringLength(data, useGrapheme);
    let valid = isMinLength(len, dataPath);
    valid = isMaxLength(len, dataPath) && valid;
    return isMatch(data, dataPath) && valid;
  };
}

/**
 * The validator of a schema's string keywords (`minLength`, `maxLength`,
 * `pattern`), or undefined when it holds none that asserts anything.
 * @param {import('./index.js').ValidationObject} schemaObj
 * @param {object} jsonSchema
 * @param {{ other: (data: unknown, dataPath: string) => boolean, taken: boolean } | null} [typed] -
 *   A leading `type: 'string'` no other keyword group precedes, in the
 *   first-failure mode: the validator then tests it too, answering a value
 *   that is no string through `typed.other`, and sets `typed.taken`
 * @returns {Function | undefined}
 */
export function compileStringBasic(schemaObj, jsonSchema, typed = null) {
  const intern = compileStringIntern(schemaObj, jsonSchema);
  if (intern == null) return undefined;
  // what a value that is no string answers: true, or the leading type's answer
  const other = typed === null ? null : typed.other;
  if (typed !== null) typed.taken = true;

  // Fast path for simple maxLength-only schemas (most common case)
  // This inlines the validation to reduce function call overhead
  const max = getIntishType(jsonSchema.maxLength) ?? -1;
  const min = getIntishType(jsonSchema.minLength) || 0;
  const hasPattern = jsonSchema.pattern != null;
  const unit = lengthUnitOf(schemaObj.options);
  const useGrapheme = unit === 'grapheme';

  if (!hasPattern) {
    if (unit === 'codepoint') {
      if (max >= 0 && min < 1) {
        const addError = schemaObj.createErrorHandler(max, 'maxLength');
        return function validateStringMaxLengthCodePoints(data, dataPath) {
          if (!isStringType(data)) return other === null || other(data, dataPath);
          const len = countCodePoints(data);
          return len <= max || addError(len, dataPath);
        };
      }

      if (min > 0 && max < 0) {
        const addError = schemaObj.createErrorHandler(min, 'minLength');
        return function validateStringMinLengthCodePoints(data, dataPath) {
          if (!isStringType(data)) return other === null || other(data, dataPath);
          const len = countCodePoints(data);
          return len >= min || addError(len, dataPath);
        };
      }
    } else if (!useGrapheme) {
      // Simple maxLength-only without grapheme counting
      if (max >= 0 && min < 1) {
        const addError = schemaObj.createErrorHandler(max, 'maxLength');
        return function validateStringMaxLength(data, dataPath) {
          if (!isStringType(data)) return other === null || other(data, dataPath);
          return data.length <= max || addError(data.length, dataPath);
        };
      }

      // Simple minLength-only without grapheme counting
      if (min > 0 && max < 0) {
        const addError = schemaObj.createErrorHandler(min, 'minLength');
        return function validateStringMinLength(data, dataPath) {
          if (!isStringType(data)) return other === null || other(data, dataPath);
          return data.length >= min || addError(data.length, dataPath);
        };
      }
    } else {
      // Fast path WITH grapheme counting - inline the ASCII fast-path logic
      // This avoids the function call overhead of getStringLength for ASCII strings
      if (max >= 0 && min < 1) {
        const addError = schemaObj.createErrorHandler(max, 'maxLength');
        return function validateStringMaxLengthGrapheme(data, dataPath) {
          if (!isStringType(data)) return other === null || other(data, dataPath);
          const len = getStringLength(data, true);
          return len <= max || addError(len, dataPath);
        };
      }

      if (min > 0 && max < 0) {
        const addError = schemaObj.createErrorHandler(min, 'minLength');
        return function validateStringMinLengthGrapheme(data, dataPath) {
          if (!isStringType(data)) return other === null || other(data, dataPath);
          const len = getStringLength(data, true);
          return len >= min || addError(len, dataPath);
        };
      }
    }
  }

  // Fast path for pattern-only schemas (common in ecmascript-regex tests)
  // This eliminates the intermediate function call overhead
  if (hasPattern && max < 0 && min < 1) {
    const pattern = jsonSchema.pattern;
    const matches = createSchemaPatternTester(pattern);
    if (matches !== undefined) {
      const addError = schemaObj.createErrorHandler(pattern, 'pattern');
      return function validateStringPatternOnly(data, dataPath) {
        if (!isStringType(data)) return other === null || other(data, dataPath);
        return matches(data) || addError(data, dataPath);
      };
    }
  }

  // Generic case
  return function validateStringBasic(data, dataPath) {
    if (!isStringType(data)) return other === null || other(data, dataPath);
    return intern(data, dataPath);
  };
}
